-- Squashed quest and guide schema/data (formerly V24-V34).
-- Deploy only when Flyway migrations V24 and later have not been applied.

CREATE TABLE `quest_post` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_published` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_quest_post_title` (`title`),
  KEY `idx_quest_post_published_sort` (`is_published`,`sort_order`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `quest_post` VALUES (1,'All eyes one me!!','SUB','https://bbs.ruliweb.com/game/77673/read/9457703',1,10,'2026-08-29 06:01:25','2026-08-29 06:17:52'),(2,'꿈인가 현실인가','SUB','https://bbs.ruliweb.com/game/77673/read/9457708',1,20,'2026-08-29 10:40:23','2026-08-29 10:40:23'),(3,'조용한 뒤틀림','SUB','https://gall.dcinside.com/mgallery/board/view/?id=digimontime&no=3256&search_head=10&page=3',1,30,'2026-08-29 10:40:23','2026-08-29 10:40:23'),(4,'깨끗한 물 찾기','SUB','https://raiderking.com/digimon-story-time-stranger-where-to-find-clean-seawater-marineangemon-sidequest/',1,40,'2026-08-29 10:40:23','2026-08-29 10:40:23'),(5,'다크 필드 워프 정리','GUIDE',NULL,1,50,'2026-08-29 10:52:19','2026-08-29 10:52:19'),(6,'아우터 던전 위치 정리','GUIDE',NULL,1,60,'2026-08-29 11:19:03','2026-08-29 11:19:03');
CREATE TABLE `quest_translation` (
  `quest_post_id` bigint unsigned NOT NULL,
  `language_code` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci,
  `source_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`quest_post_id`,`language_code`),
  CONSTRAINT `fk_quest_translation_post` FOREIGN KEY (`quest_post_id`) REFERENCES `quest_post` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_quest_translation_language` CHECK ((`language_code` in (_utf8mb4'ko',_utf8mb4'en',_utf8mb4'jp')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `quest_translation` VALUES (1,'en','All eyes one me!!','Follow the screenshots to find Etemon\'s Souls in order.','This quest can only be accepted and completed in the Real World eight years ago.',NULL),(1,'jp','All eyes one me!!','画像を見ながらエテモンのソウルの場所を順番に確認できます。','このクエストは8年前の現実世界でのみ受注・攻略できます。',NULL),(1,'ko','All eyes one me!!','에테몬의 소울을 찾는 순서와 위치를 이미지로 확인할 수 있습니다.','해당 퀘스트는 8년 전 현실세계에서만 수주하고 공략할 수 있습니다.',NULL),(2,'en','Dreams or Reality','Find all 13 Hiroko Sagisaka data monikers scattered across the Digital World.','Past and present versions of an area count as separate locations. Follow the locations below to collect every moniker.','https://raiderking.com/digimon-story-time-stranger-all-hiroko-sagisaka-moniker-locations/'),(2,'jp','夢か現実か','鷺坂ひろこのモニカの場所を画像の順番で確認できます。',NULL,NULL),(2,'ko','꿈인가 현실인가','사기사카 히로코의 모니카 위치를 이미지 순서대로 확인할 수 있습니다.',NULL,NULL),(3,'en','Quiet Distortion','Find the 13 Kuramon appearing across present-day Shinjuku and Akihabara.','Follow each area name and map marker to defeat every Kuramon and collect all of the core fragments.',NULL),(3,'jp','静かな歪み','現代の新宿と秋葉原に現れたクラモン13体の場所を確認できます。','各画像のエリア名とマップ上の位置をたどり、クラモンを倒してコアの欠片をすべて集めてください。',NULL),(3,'ko','조용한 뒤틀림','현대 신주쿠와 아키하바라에 나타난 쿠라몬 13마리의 위치를 확인할 수 있습니다.','각 이미지의 지역명과 지도에 표시된 위치를 따라 쿠라몬을 쓰러뜨리고 코어 파편을 모두 모으세요.',NULL),(4,'en','Finding Clean Water','Find the correct place to gather clean seawater for MarineAngemon.','Most gathering points at Abyss Beach give Funky Seawater. Go to the upper-left of the map and collect water from the large golden gear on the lower ledge.','https://raiderking.com/digimon-story-time-stranger-where-to-find-clean-seawater-marineangemon-sidequest/'),(4,'jp','きれいな水探し','マリンエンジェモンに渡すきれいな海水の正しい採取場所を確認できます。','アビス海岸のほとんどの採取地点では変な海水を入手します。マップ左上の低い場所にある大きな金色の歯車で、きれいな海水を採取してください。',NULL),(4,'ko','깨끗한 물 찾기','마린엔젤몬에게 가져다줄 깨끗한 바닷물의 정확한 채집 위치를 확인할 수 있습니다.','어비스 해변의 대부분 채집 지점에서는 이상한 바닷물을 얻게 됩니다. 지도의 왼쪽 위, 낮은 지대에 있는 커다란 황금색 기어 위에서 깨끗한 바닷물을 채집하세요.',NULL),(5,'en','Dark Field Warp Guide','Check the warp routes and treasure chest locations in the Dark Field images.',NULL,NULL),(5,'jp','ダークフィールド ワープ案内','ダークフィールドのワープ経路と宝箱の位置を画像で確認できます。',NULL,NULL),(5,'ko','다크 필드 워프 정리','다크 필드의 워프 경로와 상자 위치를 이미지로 확인할 수 있습니다.',NULL,NULL),(6,'en','Outer Dungeon Locations','Find all 20 Outer Dungeons in dungeon-theme order.','If the Outer Dungeon is not visible at the listed location, use DigiAttack to interact with it.',NULL),(6,'jp','アウターダンジョンの場所まとめ','全20か所のアウターダンジョンをテーマ順に確認できます。','該当する場所でアウターダンジョンが見えない場合は、デジアタックでインタラクトしてください。',NULL),(6,'ko','아우터 던전 위치 정리','아우터 던전 20개의 위치를 던전 테마 순서대로 확인할 수 있습니다.','해당 위치에서 아우터 던전이 보이지 않으면 디지어택으로 상호작용하세요.',NULL);
CREATE TABLE `quest_image` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `quest_post_id` bigint unsigned NOT NULL,
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_quest_image_post_sort` (`quest_post_id`,`sort_order`),
  CONSTRAINT `fk_quest_image_post` FOREIGN KEY (`quest_post_id`) REFERENCES `quest_post` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
