CREATE TABLE `quest_image_translation` (
  `quest_image_id` bigint unsigned NOT NULL,
  `quest_post_id` bigint unsigned NOT NULL,
  `language_code` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL,
  `location_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `location_note` text COLLATE utf8mb4_unicode_ci,
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`quest_image_id`,`language_code`),
  KEY `idx_quest_image_translation_post` (`quest_post_id`),
  CONSTRAINT `fk_quest_image_translation_image` FOREIGN KEY (`quest_image_id`) REFERENCES `quest_image` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_quest_image_translation_post` FOREIGN KEY (`quest_post_id`) REFERENCES `quest_post` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_quest_image_translation_language` CHECK ((`language_code` in (_utf8mb4'ko',_utf8mb4'en',_utf8mb4'jp')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
